-- Refresh daily skin pool (keep CASH rows)
DELETE FROM daily_drops WHERE reward_type = 'SKIN';
INSERT INTO daily_drops (reward_type, item_id, cash_amount, weight)
SELECT 'SKIN', i.id, NULL, d.weight
FROM (VALUES
    ('AK_47_SLATE', 20),
    ('AUG_TOM_CAT', 39),
    ('AUG_TRIQUA', 38),
